// parseDays parses a comma-separated list of day names. An unknown name
// is an error, since the spec comes from user input.
func parseDays(s string) ([]time.Weekday, error) {
	var days []time.Weekday
	for tok := range strings.SplitSeq(s, ",") {
		d, ok := dayNames[strings.ToLower(strings.TrimSpace(tok))]
		if !ok {
			return nil, fmt.Errorf("schedule: unknown day %q", strings.TrimSpace(tok))
		}
		if !slices.Contains(days, d) {
			days = append(days, d)
		}
	}
	slices.Sort(days)
